import React, { useState } from 'react';
import axios from 'axios';

const Login = ({ setShowLoginModal, handleLoginSubmit }) => {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');

    const handleFormSubmit = (e) => {
        e.preventDefault();
        // කෙලින්ම App.js එකේ තියෙන handleLoginSubmit එකට යනවා
        handleLoginSubmit(username, password);
    };

    return (
        <div style={{ position: 'fixed', top: '0', left: '0', width: '100%', height: '100%', background: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
            <div style={{ background: '#fff', padding: '30px', borderRadius: '10px', width: '300px' }}>
                <h2>Login</h2>
                <form onSubmit={handleFormSubmit}>
                    <input type="text" placeholder="Username" onChange={(e) => setUsername(e.target.value)} style={{ width: '100%', padding: '8px', marginBottom: '10px' }} /><br/>
                    <input type="password" placeholder="Password" onChange={(e) => setPassword(e.target.value)} style={{ width: '100%', padding: '8px', marginBottom: '10px' }} /><br/>
                    <button type="submit" style={{ width: '100%', padding: '10px', background: 'green', color: 'white', border: 'none', borderRadius: '5px', cursor: 'pointer' }}>Login</button>
                    <button type="button" onClick={() => setShowLoginModal(false)} style={{ width: '100%', padding: '10px', marginTop: '10px', cursor: 'pointer' }}>Cancel</button>
                </form>
            </div>
        </div>
    );
};

export default Login;
